<template>
  <div class="commerce-page"><header class="commerce-heading"><div><p class="eyebrow">HANDLE WITH CARE</p><h1>订单与物流</h1><p class="intro">认真对待每一份期待，让好物准时出发。</p></div><el-button size="large" :loading="loading" @click="load"><i class="ph ph-arrows-clockwise" /> 刷新订单</el-button></header><section class="surface" v-loading="loading"><el-table :data="rows" empty-text="暂无订单，商品上架后就可以迎接第一位买家了"><el-table-column label="商品 / 订单" min-width="205"><template #default="{row}"><strong>{{ row.productTitle || '历史商品' }}</strong><small class="order-sub">订单 {{ row.orderId }}<br />{{ time(row.createdAt) }}</small></template></el-table-column><el-table-column label="实付金额" width="115"><template #default="{row}"><span class="order-price">¥ {{ Number(row.unitPrice||0).toFixed(2) }}</span></template></el-table-column><el-table-column label="收货信息" min-width="210"><template #default="{row}"><p class="address-text">{{ row.shippingAddress || '未记录收货信息' }}</p><small class="order-sub">{{ row.shipOrigin }}发货</small></template></el-table-column><el-table-column label="物流状态" min-width="185"><template #default="{row}"><span class="shipment-status" :class="`s${row.status}`">{{ states[row.status] }}</span><p v-if="row.logisticsInfo" class="logistics-copy">{{ row.logisticsInfo }}</p><span v-if="row.afterSaleStatus===1" class="after-sale-label">有待处理售后</span></template></el-table-column><el-table-column label="操作" width="125" fixed="right"><template #default="{row}"><el-button v-if="row.status!==2" text type="primary" @click="open(row,'logistics')">{{ row.status===0?'安排发货':'更新物流' }}</el-button><el-button v-if="row.afterSaleStatus===1" text type="warning" @click="open(row,'after-sale')">处理售后</el-button><el-button v-else-if="row.afterSaleStatus===2" text @click="open(row,'view')">查看售后</el-button><span v-else-if="row.status===2" class="order-sub">订单已完成</span><el-button v-if="row.status===2&&row.afterSaleStatus!==1" text type="danger" @click="removeOrder(row)">删除记录</el-button></template></el-table-column></el-table><el-pagination v-if="total>12" v-model:current-page="page" class="commerce-pager" :page-size="12" :total="total" layout="total, prev, pager, next" @current-change="load" /></section>
    <el-dialog v-model="visible" :title="mode==='logistics'?'让这份好物出发':mode==='view'?'售后记录':'处理买家售后'" width="580px" class="commerce-dialog" :close-on-click-modal="false"><template v-if="current"><div class="order-dialog-summary"><strong>{{ current.productTitle }}</strong><p>订单 {{ current.orderId }}</p><p v-if="mode==='logistics'">收货信息：{{ current.shippingAddress }}</p><p v-else>买家申请：{{ current.afterSaleContent }}</p></div><el-form label-position="top" size="large"><el-form-item v-if="mode==='logistics'" label="承运快递、运单号与物流说明"><el-input v-model="text" type="textarea" :rows="4" maxlength="255" show-word-limit placeholder="例如：顺丰速运 SF123456789，已揽收，从杭州市发出" /></el-form-item><el-form-item v-else label="商家处理说明"><el-input v-model="text" type="textarea" :rows="4" maxlength="500" show-word-limit :readonly="mode==='view'" placeholder="请说明处理方式、退款或退换货安排" /></el-form-item></el-form></template><template #footer><el-button :disabled="saving" @click="visible=false">关闭</el-button><el-button v-if="mode!=='view'" type="primary" :loading="saving" @click="save">{{ mode==='logistics'?'保存物流并标记已发货':'保存处理结果' }}</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { ref, onMounted } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { merchantList, shipMerchantOrder, replyMerchantAfterSale, deleteMerchantOrder } from '@/api/merchant'
const rows=ref([]),total=ref(0),page=ref(1),loading=ref(false),visible=ref(false),current=ref(null),mode=ref('logistics'),text=ref(''),saving=ref(false)
const states={0:'等待发货',1:'运输途中',2:'已确认收货'}
const time=v=>v?String(v).replace('T',' ').slice(0,16):'—'
async function load(){loading.value=true;try{const r=await merchantList('orders',{page:page.value,size:12});rows.value=r.data.list;total.value=r.data.total}catch{}finally{loading.value=false}}
function open(row,kind){current.value=row;mode.value=kind;text.value=kind==='logistics'?row.logisticsInfo||'':row.afterSaleReply||'';visible.value=true}
async function save(){if(saving.value)return;if(!text.value.trim()){ElMessage.warning('请填写处理信息');return}saving.value=true;try{if(mode.value==='logistics')await shipMerchantOrder(current.value.orderId,{logisticsInfo:text.value});else await replyMerchantAfterSale(current.value.orderId,{reply:text.value});ElMessage.success('已保存');visible.value=false;await load()}catch{}finally{saving.value=false}}
async function removeOrder(row){const ok=await ElMessageBox.confirm('仅从你的历史订单列表移除，买家的订单与评价仍然保留。','删除历史订单',{confirmButtonText:'删除记录',cancelButtonText:'取消',type:'warning'}).then(()=>true).catch(()=>false);if(!ok)return;try{await deleteMerchantOrder(row.orderId);ElMessage.success('订单记录已删除');await load()}catch{}}
onMounted(load)
</script>
<style scoped>
.order-sub{display:block;font-size:11px;color:#9ca58f;line-height:1.8;margin-top:7px}.order-price{font-weight:700;color:#a17b46}.address-text,.logistics-copy{font-size:12px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;margin:5px 0}.logistics-copy{color:#8f9a84}.shipment-status{font-size:11px;padding:5px 9px;border-radius:6px;background:#edf1e6;color:#7c8f5c}.s0{background:#fff0d7;color:#b58b45}.s1{background:#e9f1f5;color:#6d95a6}.after-sale-label{display:block;font-size:11px;color:#bd6e48;margin-top:8px}.order-dialog-summary{padding:20px;border-radius:14px;background:#f3f5ed;margin-bottom:22px}.order-dialog-summary strong{color:#3c563e}.order-dialog-summary p{font-size:12px;line-height:1.9;color:#8c987e;margin:8px 0 0}
</style>
